#[path="../src/sync_service.rs"]
mod sync_service;
use sync_service::*;
use novel_storage::{Storage,Scene,SyncCursor};
use serde_json::json;
use std::{sync::Arc,net::SocketAddr};
use tokio::io::{AsyncReadExt,AsyncWriteExt};
async fn setup()->(tempfile::TempDir,Arc<Storage>,Arc<SyncService>,String){let d=tempfile::tempdir().unwrap();let store=Arc::new(Storage::open(&d.path().join("server.sqlite")).await.unwrap());let p=store.create_project("Private").await.unwrap();let service=SyncService::open(store.clone(),d.path().join("auth.json")).await.unwrap();(d,store,service,p.id)}
fn device()->DeviceIdentity{DeviceIdentity{device_id:"device-one".into(),device_epoch:"epoch-one".into(),name:"Synthetic peer".into()}}
fn completion(c:&PairingChallenge)->PairingCompletion{PairingCompletion{challenge_id:c.challenge_id.clone(),challenge:c.challenge.clone(),device_id:c.identity.device_id.clone(),device_epoch:c.identity.device_epoch.clone()}}
async fn grant(service:&SyncService,pid:&str)->PairingGrant{let challenge=service.create_pairing_challenge(device(),vec![pid.into()],60).await.unwrap();service.complete_pairing(completion(&challenge)).await.unwrap()}
fn request(pid:&str,op:&str,payload:serde_json::Value)->RemoteRequest{RemoteRequest{protocol_version:1,device_id:"device-one".into(),device_epoch:"epoch-one".into(),project_id:pid.into(),operation:op.into(),payload}}
#[tokio::test]
async fn scoped_pairing_replay_identity_expiry_hash_at_rest_and_revocation(){let(d,store,service,pid)=setup().await;let challenge=service.create_pairing_challenge(device(),vec![pid.clone()],60).await.unwrap();let mut wrong=completion(&challenge);wrong.device_epoch="attacker-epoch".into();assert_eq!(service.complete_pairing(wrong).await.unwrap_err().code,"authentication");let grant=service.complete_pairing(completion(&challenge)).await.unwrap();assert_eq!(service.complete_pairing(completion(&challenge)).await.unwrap_err().code,"authentication");let raw=std::fs::read_to_string(d.path().join("auth.json")).unwrap();assert!(!raw.contains(&grant.token));assert!(!raw.contains(&challenge.challenge));#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;assert_eq!(std::fs::metadata(d.path().join("auth.json")).unwrap().permissions().mode()&0o777,0o600);}assert!(service.handle(&grant.token,request(&pid,"manifest",json!({}))).await.is_ok());let other=store.create_project("Not approved").await.unwrap();assert_eq!(service.handle(&grant.token,request(&other.id,"manifest",json!({}))).await.unwrap_err().code,"authorization");assert_eq!(service.handle("bad",request(&pid,"manifest",json!({}))).await.unwrap_err().code,"authentication");service.revoke_device("device-one").await.unwrap();assert_eq!(service.handle(&grant.token,request(&pid,"manifest",json!({}))).await.unwrap_err().code,"authentication");assert!(service.create_pairing_challenge(device(),vec![pid],60).await.is_err());}
#[tokio::test]
async fn private_wrapper_replica_retry_wrong_epoch_and_no_provider_passthrough(){let(_d,server,service,pid)=setup().await;let grant=grant(&service,&pid).await;let peer_dir=tempfile::tempdir().unwrap();let peer=Storage::open(&peer_dir.path().join("peer.sqlite")).await.unwrap();let chapter=server.create_chapter(&pid,"C").await.unwrap();let first=server.create_scene(&chapter.id,Scene{schema_version:1,title:"Scene".into(),document:json!({"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مَ 世界 😀"}]}]})}).await.unwrap();let hub=server.sync_cursor().await.unwrap();let page=service.handle(&grant.token,request(&pid,"pull",json!({"cursor":{"epoch":hub.epoch,"sequence":0},"limit":1000}))).await.unwrap();let local=peer.sync_cursor().await.unwrap();peer.ingest_revisions(&pid,&local.epoch,&hub.epoch,server.open_project(&pid).await.unwrap(),serde_json::from_value(page["revisions"].clone()).unwrap()).await.unwrap();let baseline=peer.sync_cursor().await.unwrap().sequence;let mut edited=first.scene;edited.title="Peer revised".into();let edited=peer.save_scene(&first.id,edited,Some(first.revision_id)).await.unwrap();let remote=peer.sync_cursor().await.unwrap();let changes=peer.pull_revisions(&pid,SyncCursor{epoch:remote.epoch,sequence:baseline},100).await.unwrap();let push=request(&pid,"push",json!({"expectedEpoch":hub.epoch,"remoteEpoch":"epoch-one","manifest":peer.open_project(&pid).await.unwrap(),"revisions":changes.revisions}));let saved=service.handle(&grant.token,push.clone()).await.unwrap();assert_eq!(saved["inserted"],1);let retry=service.handle(&grant.token,push).await.unwrap();assert_eq!(retry["duplicates"],1);assert_eq!(server.load_scene(&first.id).await.unwrap(),edited);assert_eq!(service.handle(&grant.token,request(&pid,"provider_run",json!({"endpoint":"https://cloud.invalid"}))).await.unwrap_err().code,"unsupported_operation");server.rotate_epoch().await.unwrap();assert_eq!(service.handle(&grant.token,request(&pid,"manifest",json!({}))).await.unwrap_err().code,"stale_cursor");}
#[tokio::test]
async fn explicit_loopback_listener_strict_http_and_shutdown(){let(_d,_store,service,pid)=setup().await;assert!(service.start_listener("0.0.0.0:0".parse::<SocketAddr>().unwrap()).await.is_err());assert!(service.start_listener("192.168.1.1:0".parse::<SocketAddr>().unwrap()).await.is_err());assert!(service.start_listener("8.8.8.8:0".parse::<SocketAddr>().unwrap()).await.is_err());let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let address=listener.address;let mut stream=tokio::net::TcpStream::connect(address).await.unwrap();stream.write_all(b"GET /v1/status HTTP/1.1\r\nHost: localhost\r\n\r\n").await.unwrap();let mut response=String::new();stream.read_to_string(&mut response).await.unwrap();assert!(response.starts_with("HTTP/1.1 200"));assert!(!response.contains(&pid));let mut stream=tokio::net::TcpStream::connect(address).await.unwrap();stream.write_all(b"POST /v1/sync HTTP/1.1\r\nHost: localhost\r\nContent-Length: 0\r\nContent-Length: 999\r\n\r\n").await.unwrap();let mut response=String::new();stream.read_to_string(&mut response).await.unwrap();assert!(response.starts_with("HTTP/1.1 400"));listener.stop().await;assert!(tokio::net::TcpStream::connect(address).await.is_err());}
#[tokio::test]
async fn token_expiry_challenge_expiry_and_restored_hub_force_repair(){let(d,store,service,pid)=setup().await;let grant=grant(&service,&pid).await;drop(service);let mut auth:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(d.path().join("auth.json")).unwrap()).unwrap();auth["devices"][0]["expiresAt"]=json!(0);std::fs::write(d.path().join("auth.json"),auth.to_string()).unwrap();let service=SyncService::open(store.clone(),d.path().join("auth.json")).await.unwrap();assert_eq!(service.handle(&grant.token,request(&pid,"manifest",json!({}))).await.unwrap_err().code,"authentication");let challenge=service.create_pairing_challenge(DeviceIdentity{device_id:"device-two".into(),device_epoch:"epoch-two".into(),name:"Second".into()},vec![pid.clone()],60).await.unwrap();drop(service);let mut auth:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(d.path().join("auth.json")).unwrap()).unwrap();auth["challenges"][0]["expiresAt"]=json!(0);std::fs::write(d.path().join("auth.json"),auth.to_string()).unwrap();let service=SyncService::open(store.clone(),d.path().join("auth.json")).await.unwrap();assert_eq!(service.complete_pairing(completion(&challenge)).await.unwrap_err().code,"authentication");drop(service);store.rotate_epoch().await.unwrap();let service=SyncService::open(store,d.path().join("auth.json")).await.unwrap();assert!(service.list_devices().await.iter().all(|d|d.revoked));}
async fn http_sync(address:SocketAddr,token:&str,request:&RemoteRequest)->serde_json::Value{let body=serde_json::to_vec(request).unwrap();let mut stream=tokio::net::TcpStream::connect(address).await.unwrap();let header=format!("POST /v1/sync HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer {token}\r\nContent-Length: {}\r\n\r\n",body.len());stream.write_all(header.as_bytes()).await.unwrap();stream.write_all(&body).await.unwrap();let mut response=Vec::new();stream.read_to_end(&mut response).await.unwrap();let index=response.windows(4).position(|w|w==b"\r\n\r\n").unwrap()+4;serde_json::from_slice(&response[index..]).unwrap()}
#[tokio::test]
async fn genuine_private_http_replication_commits_and_idempotent_retry(){let(_d,server,service,pid)=setup().await;let grant=grant(&service,&pid).await;let listener=service.start_listener("127.0.0.1:0".parse().unwrap()).await.unwrap();let chapter=server.create_chapter(&pid,"Chapter").await.unwrap();let scene=server.create_scene(&chapter.id,Scene{schema_version:1,title:"Before".into(),document:json!({"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"عَ 世界 😀"}]}]})}).await.unwrap();let remote_dir=tempfile::tempdir().unwrap();let peer=Storage::open(&remote_dir.path().join("peer.sqlite")).await.unwrap();let hub=server.sync_cursor().await.unwrap();let pulled=http_sync(listener.address,&grant.token,&request(&pid,"pull",json!({"cursor":{"epoch":hub.epoch,"sequence":0},"limit":1000}))).await;assert_eq!(pulled["ok"],true);let manifest=http_sync(listener.address,&grant.token,&request(&pid,"manifest",json!({}))).await;let local=peer.sync_cursor().await.unwrap();peer.ingest_revisions(&pid,&local.epoch,&hub.epoch,serde_json::from_value(manifest["value"].clone()).unwrap(),serde_json::from_value(pulled["value"]["revisions"].clone()).unwrap()).await.unwrap();let baseline=peer.sync_cursor().await.unwrap().sequence;let mut edited=scene.scene;edited.title="After HTTP sync".into();let saved=peer.save_scene(&scene.id,edited,Some(scene.revision_id)).await.unwrap();let remote=peer.sync_cursor().await.unwrap();let page=peer.pull_revisions(&pid,SyncCursor{epoch:remote.epoch,sequence:baseline},100).await.unwrap();let push=request(&pid,"push",json!({"expectedEpoch":hub.epoch,"remoteEpoch":"epoch-one","manifest":peer.open_project(&pid).await.unwrap(),"revisions":page.revisions}));let result=http_sync(listener.address,&grant.token,&push).await;assert_eq!(result["ok"],true);assert_eq!(result["value"]["inserted"],1);let retry=http_sync(listener.address,&grant.token,&push).await;assert_eq!(retry["value"]["duplicates"],1);assert_eq!(server.load_scene(&scene.id).await.unwrap(),saved);let forbidden=http_sync(listener.address,&grant.token,&request("not-authorized","manifest",json!({}))).await;assert_eq!(forbidden["error"]["code"],"authorization");listener.stop().await;}
#[tokio::test]
async fn asset_download_reads_scoped_bounded_chunks_and_metadata_only_finalize(){
    use novel_storage::{ProjectAsset,AssetTransferSpec};
    use sha2::{Digest,Sha256};
    let(_directory,store,service,pid)=setup().await;
    let grant=grant(&service,&pid).await;
    let content:Vec<u8>=(0..700_001).map(|index|(index%251)as u8).collect();
    let asset=ProjectAsset{id:"bounded-synthetic".into(),path:"assets/bounded.txt".into(),mime_type:"text/plain".into(),checksum:format!("{:x}",Sha256::digest(&content)),content:content.clone()};
    store.put_asset(&pid,asset.clone()).await.unwrap();
    for offset in [0usize,262144,content.len()] {
        let chunk=service.handle(&grant.token,request(&pid,"asset_download",json!({"assetId":asset.id,"offset":offset,"limit":262144}))).await.unwrap();
        let bytes:Vec<u8>=serde_json::from_value(chunk["bytes"].clone()).unwrap();
        assert_eq!(bytes,content[offset..(offset+262144).min(content.len())]);
        assert_eq!(chunk["checksum"],asset.checksum);assert_eq!(chunk["totalSize"],content.len());assert_eq!(chunk["offset"],offset);
    }
    for (offset,limit) in [(0usize,0usize),(0,262145),(content.len()+1,1)] {
        assert!(service.handle(&grant.token,request(&pid,"asset_download",json!({"assetId":asset.id,"offset":offset,"limit":limit}))).await.is_err());
    }
    assert!(service.handle(&grant.token,request(&pid,"asset_download",json!({"assetId":"missing","offset":0,"limit":1}))).await.is_err());
    let spec=AssetTransferSpec{asset_id:asset.id.clone(),path:asset.path.clone(),mime_type:asset.mime_type.clone(),checksum:asset.checksum.clone(),total_size:content.len()};
    let status=service.handle(&grant.token,request(&pid,"asset_begin",json!({"spec":spec}))).await.unwrap();
    let final_receipt=service.handle(&grant.token,request(&pid,"asset_finalize",json!({"transferId":status["transferId"]}))).await.unwrap();
    assert_eq!(final_receipt["size"],content.len());assert!(final_receipt.get("content").is_none());assert!(final_receipt.to_string().len()<1000);
}
